async Task<WebApplication> Host(){var builder=WebApplication.CreateBuilder(new WebApplicationOptions{EnvironmentName="Development"});builder.WebHost.UseUrls("http://127.0.0.1:0");builder.Logging.ClearProviders();builder.Configuration["GovernanceIntelligence:KiwulaWorkspace:Enabled"]="true";builder.Configuration["GovernanceIntelligence:KiwulaWorkspace:WritesEnabled"]="true";
 builder.Services.AddHttpContextAccessor();builder.Services.AddScoped<IComplaintActorContext,Actor>();builder.Services.AddSingleton<IComplaintOfficerDirectory>(directory);builder.Services.AddSingleton<ICommissionerReportGrantSource>(grants);builder.Services.AddSingleton(new CommissionerReportReadOptions{Enabled=true});builder.Services.AddSingleton(TimeProvider.System);builder.Services.AddScoped<ICommissionerReportReadAccess,CommissionerReportReadAccess>();builder.Services.AddScoped<ScreeningEvidenceAuditInterceptor>();builder.Services.AddDbContext<GovernanceIntelligenceDbContext>((sp,o)=>o.UseNpgsql(runtime).AddInterceptors(sp.GetRequiredService<ScreeningEvidenceAuditInterceptor>()));builder.Services.AddScoped<IManualEvidenceStore,ManualEvidenceStore>();builder.Services.AddAuthentication("test").AddScheme<AuthenticationSchemeOptions,Auth>("test",_=>{});builder.Services.AddAuthorization();builder.Services.AddControllers().AddApplicationPart(typeof(ManualEvidenceController).Assembly);var app=builder.Build();app.UseAuthentication();app.UseAuthorization();app.MapControllers();await app.StartAsync();return app;}
HttpClient Client(WebApplication host,Guid? actor,string role="Officer"){var c=new HttpClient{BaseAddress=new Uri(host.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single())};if(actor!=null){c.DefaultRequestHeaders.Add("X-Test-Actor",actor.ToString());c.DefaultRequestHeaders.Add("X-Test-Role",role);}return c;}
var route="/api/governance-intelligence/officer-assessments/"+id+"/manual-evidence";var concern=Enum.GetNames<StateLandGovernance.GovernanceIntelligence.Domain.Enums.EarlyGovernanceIndicatorType>()[0];Guid attachment;
await using(var host=await Host()){
 using var owner=Client(host,ds);using var central=Client(host,commissioner);using var foreign=Client(host,other);using var applicant=Client(host,Guid.NewGuid(),"Applicant");using var anonymous=Client(host,null);
 Check((await anonymous.GetAsync(route)).StatusCode==HttpStatusCode.Unauthorized,"Anonymous denied401");Check((await applicant.GetAsync(route)).StatusCode==HttpStatusCode.Forbidden,"Applicant cannot read verification");Check((await foreign.GetAsync(route)).StatusCode==HttpStatusCode.NotFound,"Other DS cannot enumerate creator screening");
 var initial=await owner.GetFromJsonAsync<ManualEvidenceView>(route);Check(initial!.CanVerify&&initial.History.Count==0,"Responsible DS begins with separate Unverified manual state");var centralView=await central.GetFromJsonAsync<ManualEvidenceView>(route);Check(!centralView!.CanVerify,"Explicit Commissioner read-only");
 var bytes=Encoding.UTF8.GetBytes("Fictional isolated evidence supplied and reviewed by the same responsible DS.");var key=Guid.NewGuid();
 async Task<HttpResponseMessage> Upload(HttpClient client,Guid submission,string name="record.txt",string type="text/plain",byte[]? data=null){var form=new MultipartFormDataContent();form.Add(new StringContent(submission.ToString()),"submissionKey");form.Add(new StringContent(concern),"concern");var content=new ByteArrayContent(data??bytes);content.Headers.ContentType=new(type);form.Add(content,"file",name);return await client.PostAsync(route+"/attachments",form);}
 using var uploaded=await Upload(owner,key);Check(uploaded.StatusCode==HttpStatusCode.OK,"Same responsible DS uploads evidence");var saved=await uploaded.Content.ReadFromJsonAsync<ScreeningEvidence>();attachment=saved!.Id;Check(saved.ActorId==ds&&saved.Sha256==Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)).ToLowerInvariant(),"Server stamps actor/time and source SHA256");
 using var replay=await Upload(owner,key);Check((await replay.Content.ReadFromJsonAsync<ScreeningEvidence>())!.Id==attachment,"Same attachment key replays saved bytes");Check((await Upload(owner,key,data:"changed"u8.ToArray())).StatusCode==HttpStatusCode.Conflict,"Changed attachment content conflicts409");Check((await Upload(owner,Guid.NewGuid(),"../escape.txt")).StatusCode==HttpStatusCode.BadRequest,"Unsafe filename denied");Check((await Upload(owner,Guid.NewGuid(),"fake.pdf","application/pdf")).StatusCode==HttpStatusCode.BadRequest,"Mismatched PDF denied");
 Check((await Upload(central,Guid.NewGuid())).StatusCode==HttpStatusCode.NotFound,"Commissioner cannot upload");Check((await Upload(foreign,Guid.NewGuid())).StatusCode==HttpStatusCode.NotFound,"Other DS cannot upload");
 using var download=await owner.GetAsync(route+"/attachments/"+attachment);Check((await download.Content.ReadAsByteArrayAsync()).SequenceEqual(bytes)&&download.Content.Headers.ContentDisposition?.DispositionType=="attachment"&&download.Headers.GetValues("X-Content-Type-Options").Single()=="nosniff","Authenticated forced download exact bytes/no sniff");Check((await foreign.GetAsync(route+"/attachments/"+attachment)).StatusCode==HttpStatusCode.NotFound,"Attachment privacy enforced");
 var input=new VerifyScreeningEvidence(Guid.NewGuid(),concern,0,"Verified","I reviewed this specified evidence for this concern only.",[attachment],["Fictional isolated record001"]);
 Check((await central.PostAsJsonAsync(route+"/verifications",input)).StatusCode==HttpStatusCode.NotFound,"Commissioner cannot verify");Check((await foreign.PostAsJsonAsync(route+"/verifications",input)).StatusCode==HttpStatusCode.NotFound,"Other DS cannot verify");
 Check((await owner.PostAsJsonAsync(route+"/verifications",input with{Remarks="yes"})).StatusCode==HttpStatusCode.BadRequest,"Meaningful mandatory verification remarks enforced");Check((await owner.PostAsJsonAsync(route+"/verifications",input with{AttachmentIds=[Guid.NewGuid()]})).StatusCode==HttpStatusCode.BadRequest,"Foreign evidence attachment cannot be asserted");
 using var decision=await owner.PostAsJsonAsync(route+"/verifications",input);Check(decision.StatusCode==HttpStatusCode.OK,"Unverified to Verified saves");var verification=(await decision.Content.ReadFromJsonAsync<ScreeningVerification>())!;Check(verification.PreviousStatus=="Unverified"&&verification.Status=="Verified"&&verification.Revision==1&&verification.ActorId==ds,"Typed previous/new status revision and actor retained");
 using var same=await owner.PostAsJsonAsync(route+"/verifications",input);Check((await same.Content.ReadFromJsonAsync<ScreeningVerification>())!.Id==verification.Id,"Decision replay is idempotent");Check((await owner.PostAsJsonAsync(route+"/verifications",input with{Remarks="Changed content under the same submission key."})).StatusCode==HttpStatusCode.Conflict,"Changed decision replay conflicts");
 var competing=new[]{input with{SubmissionKey=Guid.NewGuid(),ExpectedRevision=1,Decision="Rejected"},input with{SubmissionKey=Guid.NewGuid(),ExpectedRevision=1,Decision="MoreInformationRequired"}};var races=await Task.WhenAll(competing.Select(x=>owner.PostAsJsonAsync(route+"/verifications",x)));Check(races.Count(x=>x.StatusCode==HttpStatusCode.OK)==1&&races.Count(x=>x.StatusCode==HttpStatusCode.Conflict)==1,"Concurrent same concern/revision commits exactly one decision");
 var rejected=input with{SubmissionKey=Guid.NewGuid(),ExpectedRevision=2,Decision="Rejected"};Check((await owner.PostAsJsonAsync(route+"/verifications",rejected)).StatusCode==HttpStatusCode.OK,"Rejected lifecycle retained");var more=rejected with{SubmissionKey=Guid.NewGuid(),ExpectedRevision=3,Decision="MoreInformationRequired"};Check((await owner.PostAsJsonAsync(route+"/verifications",more)).StatusCode==HttpStatusCode.OK,"More Information Required lifecycle retained");
 var view=await central.GetFromJsonAsync<ManualEvidenceView>(route);Check(view!.History.Count==4&&view.History.Last().Status=="MoreInformationRequired","Commissioner reads immutable decision chain, not original rewrite");grants.Revoked=true;Check((await central.GetAsync(route)).StatusCode==HttpStatusCode.NotFound,"Live report revocation removes Commissioner evidence access");grants.Revoked=false;directory.Eligible=false;Check((await owner.GetAsync(route)).StatusCode==HttpStatusCode.NotFound,"DS directory revocation removes next access");directory.Eligible=true;
 await host.StopAsync();}
